# Kapali cevrim: y'' + 2y' + 4y = 4u,  u = 1 (birim basamak)
# RK4 ile cozup tepe degeri, tepe zamani ve %2 yerlesme suresini bul.
def deriv(x):
    y, v = x
    return (v, 4.0 - 2.0 * v - 4.0 * y)


def rk4(x, h):
    def add(a, b, c):
        return (a[0] + c * b[0], a[1] + c * b[1])
    k1 = deriv(x)
    k2 = deriv(add(x, k1, h / 2))
    k3 = deriv(add(x, k2, h / 2))
    k4 = deriv(add(x, k3, h))
    return (x[0] + h / 6 * (k1[0] + 2 * k2[0] + 2 * k3[0] + k4[0]),
            x[1] + h / 6 * (k1[1] + 2 * k2[1] + 2 * k3[1] + k4[1]))


h = 0.0005
x = (0.0, 0.0)
peak, tpeak, tset = 0.0, 0.0, 0.0
n = int(12 / h)
for i in range(n):
    t = i * h
    if x[0] > peak:
        peak, tpeak = x[0], t
    if abs(x[0] - 1.0) > 0.02:
        tset = t
    x = rk4(x, h)

print("tepe       =", round(peak, 4))
print("asim %     =", round(100 * (peak - 1), 2))
print("tepe zamani=", round(tpeak, 3))
print("ts (%2)    =", round(tset + h, 3))
